// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
// car elle empêche la coalescence parfaite des accès mémoire.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float softening = 0.001f;

    // Accumuler la force, puis diviser par la masse cible après la boucle.
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    // Chaque thread parcourt toutes les particules en mémoire globale.
    for (int j = 0; j < n; j++) {
        if (i == j) continue;

        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = dx * dx + dy * dy + dz * dz + softening;
        float invDist = rsqrtf(distSq);

        // Factoriser r^-3 avec deux produits indépendants avant le produit final.
        float invDistSq = invDist * invDist;
        float massInvDist = in[j].mass * invDist;
        float forceScale = massInvDist * invDistSq;

        fx += forceScale * dx;
        fy += forceScale * dy;
        fz += forceScale * dz;
    }

    float ax = fx / in[i].mass;
    float ay = fy / in[i].mass;
    float az = fz / in[i].mass;

    // Intégration d'Euler explicite
    Particle p = in[i];
    p.vx += ax * dt;
    p.vy += ay * dt;
    p.vz += az * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}
